import React, { Fragment } from "react";
import { useLocation } from "react-router-dom";
import { Helmet } from "react-helmet";

const SITE_URL = "https://pravindev12.github.io";
const SOCIAL_IMAGE = `${SITE_URL}/logo512.png`;

const Seo = (props) => {
  const { title, metaTitle, description, image } = props;

  const location = useLocation();
  const metaDescription = description;
  const socialImage = image || SOCIAL_IMAGE;
  const currentUrl = `${SITE_URL}${location?.pathname || "/"}`;

  return (
    <Fragment>
      <Helmet>
        <title>{title}</title>
        <meta name="title" content={metaTitle} />
        <meta name="description" content={metaDescription} />
        <meta name="author" content="Pravin Raj" />
        <link rel="canonical" href={currentUrl} />
        <meta property="og:locale" content={"en_US"} />
        <meta property="og:site_name" content="Pravin Raj" />
        <meta property="og:title" content={metaTitle} />
        <meta property="og:description" content={metaDescription} />
        <meta property="og:type" content="website" />
        <meta property="og:url" content={currentUrl} />
        <meta property="og:image" content={socialImage} />
        <meta name="twitter:card" content="summary_large_image" />
        <meta name="twitter:creator" content="@PravinDev10" />
        <meta name="twitter:title" content={metaTitle} />
        <meta name="twitter:description" content={metaDescription} />
        <meta name="twitter:image" content={socialImage} />
        <meta
          name="robots"
          content="index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"
        />
      </Helmet>
    </Fragment>
  );
};

export default Seo;
