import { Link, useSearchParams } from "react-router-dom";
import { useMemo } from "react";
import {
  posts,
  getAllTags,
  getAllCategories,
  getArchiveMonths,
  groupByMonth,
} from "content/posts";
import { formatDate } from "content/markdown";

const ReadMoreIcon = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="18"
    height="18"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M7 7h10v10"></path>
    <path d="M7 17 17 7"></path>
  </svg>
);

const BlogsScreen = () => {
  const [params, setParams] = useSearchParams();
  const tag = params.get("tag") || "";
  const month = params.get("month") || "";
  const category = params.get("category") || "";
  const q = (params.get("q") || "").toLowerCase();

  const tags = useMemo(() => getAllTags(), []);
  const categories = useMemo(() => getAllCategories(), []);
  const months = useMemo(() => getArchiveMonths(), []);

  const filtered = useMemo(() => {
    return posts.filter((p) => {
      if (tag && !p.tags.includes(tag)) return false;
      if (category && p.category !== category) return false;
      if (month && !p.date.startsWith(month)) return false;
      if (q) {
        const hay = (
          p.title +
          " " +
          p.excerpt +
          " " +
          p.tags.join(" ")
        ).toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }, [tag, category, month, q]);

  const grouped = useMemo(() => groupByMonth(filtered), [filtered]);
  const hasFilters = tag || month || category || q;

  const setParam = (key, value) => {
    const next = new URLSearchParams(params);
    if (value && next.get(key) !== value) next.set(key, value);
    else next.delete(key);
    setParams(next);
  };

  const clearAll = () => setParams(new URLSearchParams());

  return (
    <div className="page_wrapper">
      <div className="blog_header">
        <h1 className="text-10 fw-600 wow animate__ animate__fadeInUp animated">
          Blog
        </h1>
        <p className="text-muted">
          Notes on blockchain development, RWA, DeFi and white-label delivery.
        </p>
      </div>

      <div className="container blog-container">
        <div className="row blog_layout">
          {/* ---- Main list ---- */}
          <div className="col-lg-8 blog_main">
            <div className="blog_toolbar">
              <input
                type="search"
                className="blog_search"
                placeholder="Search posts…"
                defaultValue={params.get("q") || ""}
                onChange={(e) => setParam("q", e.target.value)}
                aria-label="Search posts"
              />
              {hasFilters ? (
                <div className="blog_active_filters">
                  {tag && (
                    <button className="filter_chip" onClick={() => setParam("tag", "")}>
                      #{tag} ✕
                    </button>
                  )}
                  {category && (
                    <button
                      className="filter_chip"
                      onClick={() => setParam("category", "")}
                    >
                      {category} ✕
                    </button>
                  )}
                  {month && (
                    <button
                      className="filter_chip"
                      onClick={() => setParam("month", "")}
                    >
                      {months.find((m) => m.key === month)?.label || month} ✕
                    </button>
                  )}
                  <button className="filter_clear" onClick={clearAll}>
                    Clear all
                  </button>
                </div>
              ) : null}
            </div>

            {grouped.length === 0 && (
              <p className="blog_empty text-muted">
                No posts match these filters yet.
              </p>
            )}

            {grouped.map((g) => (
              <div className="blog_month_group" key={g.key}>
                <h2 className="blog_month_heading">{g.label}</h2>
                {g.posts.map((p) => (
                  <article className="blog_card" key={p.slug}>
                    <Link to={`/blogs/${p.slug}`} className="blog_card_img">
                      <img src={p.image} alt={p.title} />
                    </Link>
                    <div className="blog_card_body">
                      <div className="blog_details_head">
                        <button
                          className="text-2 text-decoration-underline blog_cat_btn"
                          onClick={() => setParam("category", p.category)}
                        >
                          {p.category}
                        </button>
                        <span className="text-2 mb-0 fw-300 text-muted">
                          {formatDate(p.date)} · {p.minutes} min read
                        </span>
                      </div>
                      <h3 className="text-5 mt-2">
                        <Link className="blog_card_title" to={`/blogs/${p.slug}`}>
                          {p.title}
                        </Link>
                      </h3>
                      <p className="text-3 text-muted">{p.excerpt}</p>
                      <div className="blog_tags">
                        {p.tags.map((t) => (
                          <button
                            key={t}
                            className="blog_tag"
                            onClick={() => setParam("tag", t)}
                          >
                            #{t}
                          </button>
                        ))}
                      </div>
                      <Link
                        className="text-decoration-none fw-400 text-3 blog_readmore"
                        to={`/blogs/${p.slug}`}
                      >
                        Read More <ReadMoreIcon />
                      </Link>
                    </div>
                  </article>
                ))}
              </div>
            ))}
          </div>

          {/* ---- Sidebar ---- */}
          <aside className="col-lg-4 blog_sidebar">
            <div className="blog_widget">
              <h4 className="blog_widget_title">Archive</h4>
              <ul className="blog_archive">
                {months.map((m) => (
                  <li key={m.key}>
                    <button
                      className={`blog_archive_link ${
                        month === m.key ? "active" : ""
                      }`}
                      onClick={() => setParam("month", m.key)}
                    >
                      <span>{m.label}</span>
                      <span className="blog_count">{m.count}</span>
                    </button>
                  </li>
                ))}
              </ul>
            </div>

            <div className="blog_widget">
              <h4 className="blog_widget_title">Categories</h4>
              <ul className="blog_archive">
                {categories.map((c) => (
                  <li key={c.category}>
                    <button
                      className={`blog_archive_link ${
                        category === c.category ? "active" : ""
                      }`}
                      onClick={() => setParam("category", c.category)}
                    >
                      <span>{c.category}</span>
                      <span className="blog_count">{c.count}</span>
                    </button>
                  </li>
                ))}
              </ul>
            </div>

            <div className="blog_widget">
              <h4 className="blog_widget_title">Tags</h4>
              <div className="blog_tagcloud">
                {tags.map((t) => (
                  <button
                    key={t.tag}
                    className={`blog_tag ${tag === t.tag ? "active" : ""}`}
                    onClick={() => setParam("tag", t.tag)}
                  >
                    #{t.tag}
                  </button>
                ))}
              </div>
            </div>
          </aside>
        </div>
      </div>
    </div>
  );
};

export default BlogsScreen;
