import { Fragment, useMemo } from "react";
import { Link, useParams } from "react-router-dom";
import "css/blog-details.css";
import Seo from "common/seo";
import { getPostBySlug, posts } from "content/posts";
import { renderMarkdown, extractToc, formatDate } from "content/markdown";

const BlogDetail = () => {
  const { slug } = useParams();
  const post = getPostBySlug(slug);

  const html = useMemo(
    () => (post ? renderMarkdown(post.body) : ""),
    [post]
  );
  const toc = useMemo(() => (post ? extractToc(post.body) : []), [post]);

  const jumpTo = (id) => {
    const el = document.getElementById(id);
    if (el) {
      const top = el.getBoundingClientRect().top + window.scrollY - 90;
      window.scrollTo({ top, behavior: "smooth" });
    }
  };

  if (!post) {
    return (
      <div className="page_wrapper">
        <div className="container text-center py-5">
          <h1 className="text-8 fw-600 mb-3">Post not found</h1>
          <p className="text-muted mb-4">
            This post doesn’t exist or may have been moved.
          </p>
          <Link className="btn btn-dark rounded-0" to="/blogs">
            ← Back to all posts
          </Link>
        </div>
      </div>
    );
  }

  const idx = posts.findIndex((p) => p.slug === post.slug);
  const prev = posts[idx + 1]; // older
  const next = posts[idx - 1]; // newer

  return (
    <Fragment>
      <Seo
        title={`${post.title} — Pravin Raj`}
        metaTitle={post.title}
        description={post.excerpt}
        image={post.image}
      />
      <div className="page_wrapper">
        <div className="container">
          <div className="row">
            <div className="col-12 col-xs-12 col-md-8 col-xl-10 m-auto">
              <div className="blog_details_wrapper">
                <Link className="blog_back_link text-3" to="/blogs">
                  ← All posts
                </Link>
                <div className="blog_details_header">
                  <span className="fw-300 text-1">{post.category}</span>
                  <h1 className="text-8 fw-600 wow animate__ animate__fadeInUp animated">
                    {post.title}
                  </h1>
                  <p className="text-muted text-2 mb-0">
                    {formatDate(post.date)} · {post.minutes} min read
                  </p>
                </div>

                <div className="blog_img_sec">
                  <img src={post.image} alt={post.title} />
                </div>

                <div className="blog_short_desc_sec">
                  <p className="text-3">{post.excerpt}</p>
                </div>

                {toc.length > 1 && (
                  <div className="blog_select_box_sec">
                    <select
                      className="form_select"
                      onChange={(e) => e.target.value && jumpTo(e.target.value)}
                      defaultValue=""
                      aria-label="Jump to section"
                    >
                      <option value="">Table of Contents</option>
                      {toc.map((t) => (
                        <option key={t.id} value={t.id}>
                          {t.level === 3 ? "— " : ""}
                          {t.text}
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                <div
                  className="blog_details_desc_sec markdown-body"
                  dangerouslySetInnerHTML={{ __html: html }}
                />

                <div className="blog_tags blog_detail_tags">
                  {post.tags.map((t) => (
                    <Link key={t} className="blog_tag" to={`/blogs?tag=${encodeURIComponent(t)}`}>
                      #{t}
                    </Link>
                  ))}
                </div>

                <div className="blog_prevnext">
                  {prev ? (
                    <Link className="blog_prevnext_link" to={`/blogs/${prev.slug}`}>
                      ← {prev.title}
                    </Link>
                  ) : (
                    <span />
                  )}
                  {next ? (
                    <Link
                      className="blog_prevnext_link text-end"
                      to={`/blogs/${next.slug}`}
                    >
                      {next.title} →
                    </Link>
                  ) : (
                    <span />
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Fragment>
  );
};

export default BlogDetail;
