import { marked } from "marked";

marked.setOptions({ gfm: true, breaks: false });

// URL/anchor-safe slug from any string (headings, tags, categories)
export const slugify = (s = "") =>
  s
    .toString()
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");

// Rough reading time in minutes (200 wpm)
export const readingTime = (md = "") => {
  const words = md.trim().split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 200));
};

// Build a table of contents from h2/h3 markdown headings
export const extractToc = (md = "") => {
  const toc = [];
  const re = /^(#{2,3})\s+(.+)$/gm;
  let m;
  while ((m = re.exec(md))) {
    const text = m[2].replace(/[*_`]/g, "").trim();
    toc.push({ level: m[1].length, text, id: slugify(text) });
  }
  return toc;
};

// Markdown -> HTML, injecting stable ids on h2/h3 so the TOC can anchor-jump
export const renderMarkdown = (md = "") => {
  const html = marked.parse(md);
  return html.replace(/<h([23])>(.*?)<\/h\1>/g, (_full, lvl, inner) => {
    const text = inner.replace(/<[^>]+>/g, "");
    return `<h${lvl} id="${slugify(text)}">${inner}</h${lvl}>`;
  });
};

// Human date: "2026-07-03" -> "Jul 3, 2026"
export const formatDate = (iso = "") => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
};
